// Turn the incoming request into a Gemini "generateContent" body.
const body = ($input.first().json.body) || {};
const topic = (body.content || body.topic || '').trim();
if (!topic) { throw new Error('Field "content" (the topic/instructions) is required.'); }

const nSlides = Number(body.n_slides) || 6;
const tone = body.tone || '';
const audience = body.audience || '';
const instructions = body.instructions || '';

const SYSTEM_PROMPT = "You are an expert presentation designer.\nProduce a clear, well-structured slide deck as JSON.\nRules:\n- Start with one \"title\" slide and end with one \"closing\" slide.\n- Use \"content\" slides with 3-5 concise, parallel bullet points (max ~12 words each).\n- Optionally use \"section\" slides to divide major parts.\n- Add a brief \"notes\" (speaker note) to content slides.\n- Keep titles short and specific. No markdown, no emojis.";
const DECK_SCHEMA = {"type":"OBJECT","properties":{"title":{"type":"STRING"},"slides":{"type":"ARRAY","items":{"type":"OBJECT","properties":{"type":{"type":"STRING","enum":["title","content","section","closing"]},"title":{"type":"STRING"},"subtitle":{"type":"STRING"},"bullets":{"type":"ARRAY","items":{"type":"STRING"}},"notes":{"type":"STRING"}},"required":["type","title"]}}},"required":["title","slides"]};

const userLines = [
  'Create a presentation about: ' + topic,
  'Target roughly ' + nSlides + ' slides (including title and closing).',
];
if (tone) userLines.push('Tone: ' + tone + '.');
if (audience) userLines.push('Audience: ' + audience + '.');
if (instructions) userLines.push('Extra instructions: ' + instructions + '.');

const geminiBody = {
  systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
  contents: [{ role: 'user', parts: [{ text: userLines.join('\n') }] }],
  generationConfig: {
    responseMimeType: 'application/json',
    responseSchema: DECK_SCHEMA,
    temperature: 0.7,
  },
};

return [{ json: { geminiBody } }];

// Extract and validate the deck JSON returned by Gemini.
const res = $input.first().json;
const raw = res && res.candidates && res.candidates[0]
  && res.candidates[0].content && res.candidates[0].content.parts
  && res.candidates[0].content.parts[0] && res.candidates[0].content.parts[0].text;
if (!raw) {
  throw new Error('No content returned by Gemini: ' + JSON.stringify(res).slice(0, 300));
}
// Defensive: strip accidental markdown fences before parsing.
const cleaned = String(raw).replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();
let deck;
try { deck = JSON.parse(cleaned); }
catch (e) { throw new Error('Gemini did not return valid JSON deck.'); }
if (!deck.title || !Array.isArray(deck.slides) || deck.slides.length === 0) {
  throw new Error('Deck is missing a title or slides.');
}
return [{ json: { deck } }];
